// ---------- data from the server (GET /api/state). Every change goes to the API and the fresh data comes back.
let RAW=BOOT.state,REV=BOOT.rev;
const CLK=BOOT.clock,RULES=BOOT.rules,DEMO=!!BOOT.demo,ME=BOOT.me;
// Real data (Sam, 6 Nov): bills and job cards come from the billing software within seconds (27 Nov); bills are made there, not here
const LIVE=!!BOOT.live,BILLING='https://billing.bikesurgeon.online';
const billBtn=(t='Make bill')=>`<a class="btn pri" href="${BILLING}" target="_blank" rel="noopener">${ic('receipt')} ${t}</a>`;
const CASHIER=ME.role==='cashier'; // only the cashier sends reminders and marks Paytm got (the server says so too); other logins do not see those buttons (round 5)
const TODAY=CLK.today, TODAY_L=CLK.short;
const nowT=()=>CLK.frozen?CLK.now:new Date().toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:'Asia/Kolkata'}).toLowerCase().replace(/\s+/g,' ');
const OPEN_FLOAT=RULES.openFloat;      // cash left in the drawer from yesterday
const PETTY_LIMIT=RULES.pettyLimit;    // one petty cash entry above this waits for the accountant's OK
const DIFF_LIMIT=RULES.diffLimit;      // closing difference above this needs a reason
const dnum=d=>{const [dd,mm,yy]=String(d).split('-').map(Number);return Date.UTC(yy,mm-1,dd)/864e5;};
const daysAgo=d=>dnum(TODAY)-dnum(d);
// The page's lists, worked out from the server data
const S={};
function derive(){const st=RAW;
 st.jobs.forEach(j=>{j.reminded=j.remind&&j.remind.length?j.remind[j.remind.length-1].at:null;});
 S.jobs=st.jobs;S.ready=st.jobs.filter(j=>j.readyAt&&!j.inv&&!j.gone);
 S.allBills=st.bills;S.bills=st.bills.filter(b=>b.date===TODAY);S.old=st.bills.filter(b=>b.date!==TODAY&&daysAgo(b.date)<=3).sort((a,b)=>dnum(a.date)-dnum(b.date));
 S.advs=st.advs;S.vendors=st.vendors;S.vinv=st.vinv;S.petty=st.petty.filter(p=>p.date===TODAY);S.allPetty=st.petty;S.handovers=st.handovers;
 S.qrShare=st.qrShare&&st.qrShare.date===TODAY?st.qrShare.rows||[]:[];
 S.fixes=st.fixes.filter(f=>f.date===TODAY||f.st==='asked'||f.st==='ok');}
derive();
const dayLocked=()=>S.handovers.some(h=>h.date===TODAY);
let BUSY=false;
function setState(st,rev){RAW=st;if(rev!=null)REV=rev;derive();}
async function reloadState(){try{const r=await fetch('/api/state');if(r.status===401){location.reload();return;}const d=await r.json();if(d.clock&&d.clock.today!==TODAY){location.reload();return;}setState(d.state,d.rev);render();}catch(e){}}
// Other screens (advisor, Saniya, Ganesh, owner, accountant) change the same data: pick it up quickly
setInterval(async()=>{if(BUSY||OV||document.hidden)return;try{const r=await fetch('/api/rev');if(r.status===401){location.reload();return;}const d=await r.json();if(d.today&&d.today!==TODAY){location.reload();return;}if(d.rev!==REV)reloadState();}catch(e){}},DEMO?2000:3000);
async function api(method,path,body){if(BUSY)return null;BUSY=true;
 try{const r=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
  const d=await r.json().catch(()=>({}));
  if(r.status===401){location.reload();return null;}
  if(!r.ok){toast(d.error||'Could not save. Try again.');if(r.status===409){BUSY=false;await reloadState();}return null;}
  if(d.state)setState(d.state,d.rev);return d;}
 catch(e){toast('No connection. Nothing was saved, try again.');return null;}
 finally{BUSY=false;}}
// run an action, redraw, show the server's message
async function run(method,path,body,after){const d=await api(method,path,body);if(!d)return null;OV=null;if(after)after(d);else render();if(d.msg)toast(d.msg);return d;}
// Take a photo (phone camera or file), made smaller so it uploads fast. Gives a data URL.
function pickPhoto(cb){const inp=document.createElement('input');inp.type='file';inp.accept='image/*';inp.setAttribute('capture','environment');inp.style.display='none';document.body.appendChild(inp);
 inp.addEventListener('change',()=>{const f=inp.files&&inp.files[0];inp.remove();if(!f)return;const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const k=Math.min(1,1600/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*k));c.height=Math.max(1,Math.round(img.height*k));c.getContext('2d').drawImage(img,0,0,c.width,c.height);cb(c.toDataURL('image/jpeg',0.82));};img.onerror=()=>toast('This file is not a photo.');img.src=rd.result;};rd.readAsDataURL(f);});
 inp.click();}
const UI={me:ME.name,page:CASHIER||LIVE?'today':'requests',jc:null,tab:{},q:'',pay:{}};
let OV=null;
const ready=jc=>S.ready.find(r=>r.jc===jc);
const advOf=no=>S.advs.find(a=>a.no===no);
const sub=r=>sum(r.lines,l=>l[2]*l[3]);
// The cashier can make the bill only after the advisor closes the job card (Sam, 14 Oct)
const onHold=r=>r.reopen&&r.reopen.st==='asked'; // Saniya asked to reopen, the admin panel has not answered yet
const isClosed=r=>!!r.closed&&!onHold(r);const canBill=()=>S.ready.filter(isClosed);const notClosed=()=>S.ready.filter(r=>!isClosed(r));
const labourOf=r=>sum(r.lines.filter(l=>l[1]==='L'),l=>l[2]*l[3]);
const discOf=r=>r.disc&&r.disc.st==='ok'?r.disc.amt:0;
const billAmt=r=>sub(r)-discOf(r);
// advances held for this job card (its advance number, or taken on the same job card), same as the server
const heldFor=r=>S.advs.filter(a=>a.st==='open'&&(a.no===r.advNo||a.jc===r.jc));const advAmt=r=>sum(heldFor(r),a=>a.amount);
const toCollect=r=>billAmt(r)-advAmt(r);
// money received now for a bill (advance part was received earlier)
const recv=b=>b.amount-(b.advAmt||0);
const cashOf=b=>b.mode==='Cash'?recv(b):b.mode==='Split'?b.cash:0;
const upiOf=b=>b.mode==='UPI'?recv(b):b.mode==='Split'?recv(b)-b.cash-(b.card||0):0;
const cardOf=b=>b.mode==='Card'?recv(b):b.mode==='Split'?b.card||0:0;
const advToday=()=>S.advs.filter(a=>a.date===TODAY);
const retToday=()=>S.advs.filter(a=>a.ret&&a.ret.date===TODAY);
// Cancelled bills (owner said OK) drop out of every total; UPI pending = customer's bank debited but Paytm has not shown it yet
const isCancelled=b=>b.cancel&&b.cancel.st==='ok';const liveBills=()=>S.bills.filter(b=>!isCancelled(b));
const pendBills=()=>liveBills().filter(b=>b.upiPend&&b.upiPend.st==='pending');
// real data: bills made in the billing software but not paid yet (any day of the last 40)
const unpaidBills=()=>S.allBills.filter(b=>b.mode==='Pending').sort((a,b)=>dnum(b.date)-dnum(a.date));
function totals(){const B=liveBills();const A=advToday();
 const t={n:B.length,sale:sum(B,b=>b.amount),labour:sum(B,b=>b.labour),
  cashB:sum(B.filter(b=>b.mode==='Cash'),recv),upiB:sum(B.filter(b=>b.mode==='UPI'),recv),
  spN:B.filter(b=>b.mode==='Split').length,spC:sum(B.filter(b=>b.mode==='Split'),b=>b.cash),spU:sum(B.filter(b=>b.mode==='Split'),b=>recv(b)-b.cash-(b.card||0)),
  advUsed:sum(B,b=>b.advAmt||0),advN:A.length,advC:sum(A,a=>a.cash),advU:sum(A,a=>a.upi),
  advR:sum(retToday().filter(a=>a.ret.mode==='Cash'),a=>a.ret.amt),petty:sum(S.petty.filter(p=>p.st!=='no'),p=>p.amt),
  cardB:sum(B,cardOf),cardN:B.filter(b=>cardOf(b)>0).length,unpaid:sum(B.filter(b=>b.mode==='Pending'||b.mode==='Credit'),b=>b.amount)};
 t.cash=t.cashB+t.spC;t.upi=t.upiB+t.spU;t.got=t.cash+t.upi+t.cardB; // money received today (card too)
 t.drawer=OPEN_FLOAT+t.cash+t.advC-t.advR-t.petty; // expected cash in the drawer now
 t.paytm=t.upi+t.advU;                               // service counter's own UPI today
 // the Paytm QR is shared by the whole shop: it is matched once a day in the accountant panel (QR check), not here
 t.pend=sum(pendBills(),upiOf);    // pending UPI is not in Paytm yet
 return t;}
const MODEC={Cash:'green',UPI:'blue',Split:'violet',Card:'blue',Credit:'orange',Pending:'orange'};const MODET={Pending:'Not paid',Credit:'Credit (udhaar)'};
const modePill=b=>(isCancelled(b)?pill('Cancelled','gray')+' ':b.cancel&&b.cancel.st==='asked'?pill('Cancel asked','violet')+' ':'')+(b.upiPend&&b.upiPend.st==='pending'?pill('UPI pending','orange')+' ':'')+(b.mode==='Split'?`${pill('Split','violet')}<div><small class="muted">Cash ${inr(b.cash)} + UPI ${inr(recv(b)-b.cash-(b.card||0))}${b.card?` + Card ${inr(b.card)}`:''}</small></div>`:pill(MODET[b.mode]||b.mode,MODEC[b.mode]||'gray'));
